from collections import deque
R,C=len(grid),len(grid[0])
def comps(diag=False):
  seen=set(); out=[]
  neigh=[(i,j) for i in (-1,0,1) for j in (-1,0,1) if (i or j) and (diag or abs(i)+abs(j)==1)]
  for r in range(R):
    for c in range(C):
      if grid[r][c]!=2 or (r,c) in seen: continue
      q=[(r,c)];seen.add((r,c)); cells=[]
      for x,y in q:
        cells.append((x,y))
        for dr,dc in neigh:
          z=(x+dr,y+dc)
          if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]]==2 and z not in seen:
            seen.add(z);q.append(z)
      out.append(cells)
  return out
for diag in (False,True):
  print('\ndiag',diag)
  for cc in comps(diag):
    rs=[x for x,y in cc];cs=[y for x,y in cc]
    touched=any(r==4 or r==11 or c==5 for r,c in cc)
    print(len(cc),(min(rs),max(rs),min(cs),max(cs)), 'hit',touched)

